import{_ as t,o as i,c as a,a0 as o}from"./chunks/framework.CShDTZbC.js";const h=JSON.parse('{"title":"Phase 2B: Adversarial Ranking Review","description":"","frontmatter":{},"headers":[],"relativePath":"internals/hackathon-archive/problem-adversarial-review.md","filePath":"internals/hackathon-archive/problem-adversarial-review.md"}'),r={name:"internals/hackathon-archive/problem-adversarial-review.md"};function n(s,e,l,g,c,d){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="phase-2b-adversarial-ranking-review" tabindex="-1">Phase 2B: Adversarial Ranking Review <a class="header-anchor" href="#phase-2b-adversarial-ranking-review" aria-label="Permalink to &quot;Phase 2B: Adversarial Ranking Review&quot;">​</a></h1><h2 id="part-1-brutal-interrogation-of-the-current-top-10" tabindex="-1">Part 1: Brutal Interrogation of the Current Top 10 <a class="header-anchor" href="#part-1-brutal-interrogation-of-the-current-top-10" aria-label="Permalink to &quot;Part 1: Brutal Interrogation of the Current Top 10&quot;">​</a></h2><h3 id="_1-local-dev-environment-troubleshooter-candidate-29" tabindex="-1">1. Local Dev Environment Troubleshooter (Candidate 29) <a class="header-anchor" href="#_1-local-dev-environment-troubleshooter-candidate-29" aria-label="Permalink to &quot;1. Local Dev Environment Troubleshooter (Candidate 29)&quot;">​</a></h3><ol><li><strong>Agent Necessary?</strong> Yes. Fixing environments requires a dynamic observation-action loop (run -&gt; fail -&gt; edit -&gt; rerun).</li><li><strong>Deterministic tool sufficient?</strong> No, environment errors are infinitely varied.</li><li><strong>% Agentic:</strong> 90%.</li><li><strong>Baseline Fair?</strong> Yes (comparing against a human Googling errors).</li><li><strong>10+ Cases?</strong> Yes (10 deliberately broken Docker environments).</li><li><strong>Ground Truth?</strong> Yes (the app successfully returning HTTP 200).</li><li><strong>Objective Measurement?</strong> Yes (Success rate / Time to fix).</li><li><strong>Reproducible?</strong> Yes, via Docker.</li><li><strong>5-min Demo?</strong> Yes, highly visual terminal action.</li><li><strong>Strongest Criticism:</strong> &quot;It&#39;s a security nightmare. It could run <code>rm -rf /</code> or leak credentials.&quot;</li><li><strong>Assumption vs Evidence:</strong> Assuming the LLM won&#39;t get trapped in infinite retry loops (e.g., <code>npm cache clean</code> over and over).</li><li><strong>Lose 10+ points if:</strong> Judges can&#39;t safely run it on their own machines without fear.</li><li><strong>Minimum Viable:</strong> Fixes missing dependencies in a single <code>package.json</code>.</li><li><strong>Maximum Realistic:</strong> Fixes complex <code>docker-compose</code> network routing issues.</li><li><strong>Complexity Risk:</strong> Medium (sandboxing is hard).</li><li><strong>Existing Tools:</strong> GitHub Copilot in the CLI (though it requires human confirmation per command).</li><li><strong>Differentiation:</strong> Fully autonomous execution loop, not just a command suggester.</li><li><strong>Hot Take:</strong> LLMs are superior at debugging simply because they don&#39;t experience fatigue when reading 5,000 lines of terminal vomit.</li><li><strong>Biggest Unknown:</strong> Safely catching destructive commands before execution.</li><li><strong>Validation Experiment:</strong> Build a minimal bash-tool agent and see if it can fix a broken Python script without human intervention.</li></ol><h3 id="_2-medical-trial-eligibility-matcher-candidate-17" tabindex="-1">2. Medical Trial Eligibility Matcher (Candidate 17) <a class="header-anchor" href="#_2-medical-trial-eligibility-matcher-candidate-17" aria-label="Permalink to &quot;2. Medical Trial Eligibility Matcher (Candidate 17)&quot;">​</a></h3><ol><li><strong>Agent Necessary?</strong> <strong>NO.</strong> This is just complex text-classification/RAG. A single zero-shot prompt with a large context window does the exact same thing.</li><li><strong>Deterministic tool sufficient?</strong> No, but a non-agentic LLM is.</li><li><strong>% Agentic:</strong> &lt;10%.</li><li><strong>Baseline Fair?</strong> Yes.</li><li><strong>10+ Cases?</strong> Yes.</li><li><strong>Ground Truth?</strong> Yes, clinician labels.</li><li><strong>Objective Measurement?</strong> Yes, F1 score.</li><li><strong>Reproducible?</strong> Yes.</li><li><strong>5-min Demo?</strong> Boring (just processing text).</li><li><strong>Strongest Criticism:</strong> &quot;This is an AI hackathon from 2022. There&#39;s no agentic workflow here, just data parsing.&quot;</li><li><strong>Assumption vs Evidence:</strong> Assuming multi-step reasoning helps, when a single pass might be better.</li><li><strong>Lose 10+ points if:</strong> Judges realize it&#39;s a glorified wrapper around an API request. <em>(Note: Flagged for removal from Top 10)</em></li></ol><h3 id="_3-security-pentest-report-validator-candidate-11" tabindex="-1">3. Security Pentest Report Validator (Candidate 11) <a class="header-anchor" href="#_3-security-pentest-report-validator-candidate-11" aria-label="Permalink to &quot;3. Security Pentest Report Validator (Candidate 11)&quot;">​</a></h3><ol><li><strong>Agent Necessary?</strong> Yes. Needs to iteratively use tools (nmap, curl, sqlmap) based on intermediate outputs.</li><li><strong>Deterministic tool sufficient?</strong> No, vulnerability exploitation requires dynamic adaptation.</li><li><strong>% Agentic:</strong> 80%.</li><li><strong>Baseline Fair?</strong> Yes.</li><li><strong>10+ Cases?</strong> Yes (OWASP Juice Shop flags).</li><li><strong>Ground Truth?</strong> Yes (getting the exploit flag).</li><li><strong>Objective Measurement?</strong> Yes.</li><li><strong>Reproducible?</strong> Yes, if the vulnerable app is containerized.</li><li><strong>5-min Demo?</strong> Excellent.</li><li><strong>Strongest Criticism:</strong> &quot;It&#39;s just blindly trying pre-written Metasploit payloads until one works.&quot;</li><li><strong>Assumption vs Evidence:</strong> Assuming the agent can actually reason about the vulnerability rather than just brute-forcing.</li><li><strong>Lose 10+ points if:</strong> The exploits are too simplistic or it breaks the sandbox.</li><li><strong>Minimum Viable:</strong> Verifies a simple XSS payload.</li><li><strong>Maximum Realistic:</strong> Chains two vulnerabilities together (e.g., SSRF to LFI).</li><li><strong>Complexity Risk:</strong> High.</li><li><strong>Existing Tools:</strong> Automated vulnerability scanners (Nessus).</li><li><strong>Differentiation:</strong> Proves exploitability dynamically, eliminating false positives.</li><li><strong>Hot Take:</strong> 90% of vendor pentest reports are false positives that waste developer time.</li><li><strong>Biggest Unknown:</strong> Can an LLM handle the massive context of raw network responses?</li><li><strong>Validation Experiment:</strong> See if an agent can execute a blind SQLi with basic curl tools.</li></ol><h3 id="_4-legacy-code-translator-verifier-candidate-7" tabindex="-1">4. Legacy Code Translator &amp; Verifier (Candidate 7) <a class="header-anchor" href="#_4-legacy-code-translator-verifier-candidate-7" aria-label="Permalink to &quot;4. Legacy Code Translator &amp; Verifier (Candidate 7)&quot;">​</a></h3><ol><li><strong>Agent Necessary?</strong> Yes, for the Write -&gt; Test -&gt; Fix loop.</li><li><strong>Deterministic tool sufficient?</strong> No.</li><li><strong>% Agentic:</strong> 70%.</li><li><strong>Baseline Fair?</strong> Yes (vs zero-shot translation).</li><li><strong>10+ Cases?</strong> Yes.</li><li><strong>Ground Truth?</strong> Yes (unit tests passing).</li><li><strong>Objective Measurement?</strong> Yes.</li><li><strong>Reproducible?</strong> Highly.</li><li><strong>5-min Demo?</strong> Strong.</li><li><strong>Strongest Criticism:</strong> &quot;If the original code has no tests, your agent just hallucinates tests that pass the wrong behavior.&quot;</li><li><strong>Assumption vs Evidence:</strong> Assuming we can reliably auto-generate ground-truth tests for legacy code.</li><li><strong>Lose 10+ points if:</strong> The auto-generated tests don&#39;t actually cover edge cases.</li><li><strong>Minimum Viable:</strong> Translates a standalone Python script to Go.</li><li><strong>Maximum Realistic:</strong> Translates a script with file I/O and mocks the side effects.</li><li><strong>Complexity Risk:</strong> Medium.</li><li><strong>Existing Tools:</strong> AWS CodeWhisperer translation tools.</li><li><strong>Differentiation:</strong> The iterative compiler feedback loop.</li><li><strong>Hot Take:</strong> Zero-shot code translation is a myth; iterative compilation is the only way forward.</li><li><strong>Biggest Unknown:</strong> What if the target language lacks a library that the source language used?</li><li><strong>Validation Experiment:</strong> Manually trigger the Write-Test loop 3 times to see if Gemini actually converges on a solution.</li></ol><h3 id="_5-ux-ui-consistency-auditor-candidate-30" tabindex="-1">5. UX/UI Consistency Auditor (Candidate 30) <a class="header-anchor" href="#_5-ux-ui-consistency-auditor-candidate-30" aria-label="Permalink to &quot;5. UX/UI Consistency Auditor (Candidate 30)&quot;">​</a></h3><ol><li><strong>Agent Necessary?</strong> <strong>NO.</strong> A script can pull the Figma API, screenshot the DOM, and pass both to a multimodal model. No iterative decision-making is happening.</li><li><strong>Deterministic tool sufficient?</strong> No, but a static pipeline is.</li><li><strong>% Agentic:</strong> &lt;5%.</li><li><strong>Baseline Fair?</strong> Yes.</li><li><strong>Strongest Criticism:</strong> &quot;This is a single API call to a multimodal model. There is no &#39;agent&#39;.&quot; <em>(Note: Flagged for removal from Top 10)</em></li></ol><h3 id="_6-database-schema-migration-reviewer-candidate-8" tabindex="-1">6. Database Schema Migration Reviewer (Candidate 8) <a class="header-anchor" href="#_6-database-schema-migration-reviewer-candidate-8" aria-label="Permalink to &quot;6. Database Schema Migration Reviewer (Candidate 8)&quot;">​</a></h3><ol><li><strong>Agent Necessary?</strong> <strong>NO.</strong> A script can run <code>EXPLAIN</code>, capture the plan, and send it to an LLM for review. No autonomous loop.</li><li><strong>Strongest Criticism:</strong> &quot;It&#39;s just a linter with an LLM attached.&quot; <em>(Note: Flagged for removal from Top 10)</em></li></ol><h3 id="_7-flaky-test-root-cause-diagnoser-candidate-3" tabindex="-1">7. Flaky Test Root Cause Diagnoser (Candidate 3) <a class="header-anchor" href="#_7-flaky-test-root-cause-diagnoser-candidate-3" aria-label="Permalink to &quot;7. Flaky Test Root Cause Diagnoser (Candidate 3)&quot;">​</a></h3><ol><li><strong>Agent Necessary?</strong> Yes.</li><li><strong>Deterministic tool sufficient?</strong> No.</li><li><strong>% Agentic:</strong> 85%.</li><li><strong>Strongest Criticism:</strong> &quot;Flaky tests are by definition non-deterministic. If a judge runs it twice, they get two different results. It fails reproducibility.&quot; <em>(Note: High risk, must ensure reproducibility via synthetic, predictably flaky tests).</em></li></ol><h3 id="_8-accessibility-a11y-web-auditor-candidate-9" tabindex="-1">8. Accessibility (a11y) Web Auditor (Candidate 9) <a class="header-anchor" href="#_8-accessibility-a11y-web-auditor-candidate-9" aria-label="Permalink to &quot;8. Accessibility (a11y) Web Auditor (Candidate 9)&quot;">​</a></h3><ol><li><strong>Agent Necessary?</strong> Only if it dynamically navigates via keyboard.</li><li><strong>Strongest Criticism:</strong> &quot;Axe-core already does 90% of this deterministically for free.&quot; <em>(Note: Borderline. If it actually uses Playwright to navigate, it&#39;s agentic. If it just reads static DOM, it&#39;s not.)</em></li></ol><h3 id="_9-api-breaking-change-detector-candidate-5" tabindex="-1">9. API Breaking Change Detector (Candidate 5) <a class="header-anchor" href="#_9-api-breaking-change-detector-candidate-5" aria-label="Permalink to &quot;9. API Breaking Change Detector (Candidate 5)&quot;">​</a></h3><ol><li><strong>Agent Necessary?</strong> Borderline. It&#39;s mostly generating a test suite and running it once.</li><li><strong>Strongest Criticism:</strong> &quot;Generating a test suite isn&#39;t an agentic workflow, it&#39;s just code generation.&quot;</li></ol><h3 id="_10-terraform-iac-security-auditor-candidate-14" tabindex="-1">10. Terraform/IaC Security Auditor (Candidate 14) <a class="header-anchor" href="#_10-terraform-iac-security-auditor-candidate-14" aria-label="Permalink to &quot;10. Terraform/IaC Security Auditor (Candidate 14)&quot;">​</a></h3><ol><li><strong>Agent Necessary?</strong> <strong>NO.</strong> Static analysis + LLM.</li><li><strong>Strongest Criticism:</strong> &quot;Just another Checkov wrapper.&quot; <em>(Note: Flagged for removal).</em></li></ol><hr><h2 id="part-2-re-evaluating-the-outsiders" tabindex="-1">Part 2: Re-evaluating the Outsiders <a class="header-anchor" href="#part-2-re-evaluating-the-outsiders" aria-label="Permalink to &quot;Part 2: Re-evaluating the Outsiders&quot;">​</a></h2><ul><li><strong>#1 CI/CD Build Investigator:</strong> Could be highly agentic if it actively edits code, commits, and pushes to a local test branch until green.</li><li><strong>#2 Dependency Update Analyzer:</strong> Highly agentic. Must install the update, run tests, read the exact failure, parse the upstream repo issues to find a workaround, and apply it.</li><li><strong>#16 Scientific Paper Fact-Checker:</strong> Highly agentic if it has to iteratively crawl citation graphs, parse PDFs, and find contradicting studies.</li></ul><hr><h2 id="part-3-the-verdict" tabindex="-1">Part 3: The Verdict <a class="header-anchor" href="#part-3-the-verdict" aria-label="Permalink to &quot;Part 3: The Verdict&quot;">​</a></h2><h3 id="a-top-10-after-adversarial-review-the-true-agents-list" tabindex="-1">A. TOP 10 AFTER ADVERSARIAL REVIEW (The &quot;True Agents&quot; List) <a class="header-anchor" href="#a-top-10-after-adversarial-review-the-true-agents-list" aria-label="Permalink to &quot;A. TOP 10 AFTER ADVERSARIAL REVIEW (The &quot;True Agents&quot; List)&quot;">​</a></h3><ol><li>Local Dev Environment Troubleshooter (#29)</li><li>Security Pentest Report Validator (#11)</li><li>Legacy Code Translator &amp; Verifier (#7)</li><li>Flaky Test Root Cause Diagnoser (#3)</li><li>CI/CD Build Investigator (#1)</li><li>Dependency Update Risk Analyzer (#2)</li><li>Scientific Paper Fact-Checker (#16)</li><li>Real Estate Zoning Analyzer (#28) <em>(Iterative GIS querying &amp; PDF correlation)</em></li><li>E-commerce Catalog Normalizer (#21) <em>(Iterative web search for disambiguation)</em></li><li>API Breaking Change Detector (#5) <em>(Must be redesigned to dynamically fuzz the API)</em></li></ol><h3 id="b-3-underrated-candidates-promoted-to-top-10" tabindex="-1">B. 3 UNDERRATED CANDIDATES PROMOTED TO TOP 10 <a class="header-anchor" href="#b-3-underrated-candidates-promoted-to-top-10" aria-label="Permalink to &quot;B. 3 UNDERRATED CANDIDATES PROMOTED TO TOP 10&quot;">​</a></h3><ul><li><strong>CI/CD Build Investigator (#1)</strong> (Reframed as an active fixer, not just a log reader).</li><li><strong>Dependency Update Risk Analyzer (#2)</strong> (True autonomous testing loop).</li><li><strong>Scientific Paper Fact-Checker (#16)</strong> (Citation graph crawling is inherently agentic).</li></ul><h3 id="c-3-high-scoring-candidates-removed-from-top-10" tabindex="-1">C. 3 HIGH-SCORING CANDIDATES REMOVED FROM TOP 10 <a class="header-anchor" href="#c-3-high-scoring-candidates-removed-from-top-10" aria-label="Permalink to &quot;C. 3 HIGH-SCORING CANDIDATES REMOVED FROM TOP 10&quot;">​</a></h3><ul><li><strong>Medical Trial Eligibility Matcher (#17)</strong> (Zero agentic necessity; it&#39;s just RAG).</li><li><strong>UX/UI Consistency Auditor (#30)</strong> (Zero agentic necessity; static pipeline).</li><li><strong>Database Schema Migration Reviewer (#8)</strong> (Zero agentic necessity; static pipeline).</li></ul><h3 id="d-5-biggest-uncertainties-to-validate" tabindex="-1">D. 5 BIGGEST UNCERTAINTIES TO VALIDATE <a class="header-anchor" href="#d-5-biggest-uncertainties-to-validate" aria-label="Permalink to &quot;D. 5 BIGGEST UNCERTAINTIES TO VALIDATE&quot;">​</a></h3><ol><li>Can an LLM consistently read and understand a 5,000-line broken terminal trace without losing context?</li><li>Can we safely sandbox terminal execution so judges can test it without fear?</li><li>Will the agent get trapped in infinite loops when its proposed fix fails?</li><li>Can we reliably mock network/API responses so the workflows are 100% reproducible for judges?</li><li>Do we have the ability to objectively grade the output without a human in the loop?</li></ol><h3 id="e-recommended-validation-experiment-for-the-final-10" tabindex="-1">E. RECOMMENDED VALIDATION EXPERIMENT FOR THE FINAL 10 <a class="header-anchor" href="#e-recommended-validation-experiment-for-the-final-10" aria-label="Permalink to &quot;E. RECOMMENDED VALIDATION EXPERIMENT FOR THE FINAL 10&quot;">​</a></h3><ul><li><strong>#29 (Dev Troubleshooter):</strong> Give it a Dockerfile with a missing <code>apt-get</code> dependency. See if it fixes it and builds successfully.</li><li><strong>#11 (Pentest):</strong> Spin up a local vulnerable server. Tell the agent to find the flag.</li><li><strong>#7 (Legacy Code):</strong> Ask it to convert a Python script to JS and auto-verify it against the Python script&#39;s output.</li><li><strong>#3 (Flaky Tests):</strong> Create a test that fails 50% of the time due to a race condition. See if the agent can isolate it.</li><li><strong>#1 (CI/CD):</strong> Break a local GitHub Action. Run the agent and see if it proposes the exact git diff needed to fix it.</li><li><strong>#2 (Dependencies):</strong> Force a breaking version bump locally. Ask the agent to find the migration guide and rewrite the local code.</li><li><strong>#16 (Sci Fact-Check):</strong> Give it a PDF with a fake citation. See if it can use Scholar APIs to prove it&#39;s fake.</li><li><strong>#28 (Real Estate):</strong> Give it a local Zoning PDF and ask a complex spatial constraint question.</li><li><strong>#21 (Catalog):</strong> Feed it 10 obscure product names and see if it can web-search to categorize them.</li><li><strong>#5 (API Break):</strong> Change an API payload locally. See if the agent can dynamically discover the break without a schema.</li></ul>',37)])])}const m=t(r,[["render",n]]);export{h as __pageData,m as default};
